const dayNum=iso=>{const p=iso.split('-').map(Number);return Math.floor(Date.UTC(p[0],p[1]-1,p[2])/864e5);};
const isoOf=n=>new Date(n*864e5).toISOString().slice(0,10);
const dowOf=iso=>new Date(dayNum(iso)*864e5).getUTCDay();
const md=iso=>{const p=iso.split('-').map(Number);return p[1]+'/'+p[2]+'('+DOWS[dowOf(iso)]+(HOLIDAYS[iso]?'・祝':'')+')';};
const mins=hm=>{const p=hm.split(':').map(Number);return p[0]*60+p[1];};
function km(a,b,c,d){const R=6371,r=Math.PI/180,x=(c-a)*r,y=(d-b)*r,h=Math.sin(x/2)**2+Math.cos(a*r)*Math.cos(c*r)*Math.sin(y/2)**2;return 2*R*Math.asin(Math.sqrt(h));}
const openOn=(ev,iso)=>(ev.hx&&ev.hx[iso]&&ev.hx[iso][0])||ev.o;
const closeOn=(ev,iso)=>(ev.hx&&ev.hx[iso]&&ev.hx[iso][1])||(ev.late&&ev.late[dowOf(iso)])||ev.c;
const activeOn=(ev,iso)=>ev.s<=iso&&iso<=ev.e&&!ev.off.includes(iso);
const daysLeft=(ev,iso)=>dayNum(ev.e)-dayNum(iso);
const longRun=ev=>dayNum(ev.e)-dayNum(ev.s)>=7;
// その日の中での状態: now=開催中, next=これから, over=終了
function stateAt(ev,iso,nowMin){const o=mins(openOn(ev,iso)),c=mins(closeOn(ev,iso));return nowMin<o?'next':nowMin<c?'now':'over';}
function travel(d){return d<=1.5?'徒歩で約'+Math.max(1,Math.round(d*16))+'分':'電車などで約'+Math.round((10+d*2.5)/5)*5+'分';}
function search(q){
  let rows=EV.filter(ev=>activeOn(ev,q.day)&&q.genres.has(ev.g));
  if(q.free)rows=rows.filter(ev=>ev.free);
  if(q.soon)rows=rows.filter(ev=>longRun(ev)&&daysLeft(ev,q.day)<=7);
  if(q.night)rows=rows.filter(ev=>mins(closeOn(ev,q.day))>=19*60);
  rows=rows.map(ev=>({ev,dist:q.from?km(SPOTS[q.from][0],SPOTS[q.from][1],ev.lat,ev.lng):null,state:q.nowMin==null?null:stateAt(ev,q.day,q.nowMin)}));
  if(q.nowOnly)rows=rows.filter(r=>r.state!=='over');
  rows.sort((a,b)=>q.from?a.dist-b.dist:(mins(a.ev.o)-mins(b.ev.o))||a.ev.e.localeCompare(b.ev.e));
  return rows;
}
